// Ridge: a filled silhouette that rises from the stage floor with the raw spectrum, drawn on a 2D canvas.
// Written by hand for the raw form; the other fixtures are generated by tools/vis-port.mjs.
(() => {
  const { BAND_COUNT, smoothBands } = plistoVis;

  // Fast attack, slow decay: the ridge snaps up on a hit and eases back down.
  const ATTACK = 0.5;
  const DECAY = 0.15;
  // The silhouette rises to this fraction of the stage height at a full band.
  const MAX_AMP = 0.82;
  // The fill alpha at the floor, easing to nothing near the top so the ridge melts into the ground.
  const BASE_ALPHA = 0.5;
  const MID_ALPHA = 0.16;

  // A calm shallow arch, tallest in the middle: the still frame and the reduced-motion shape.
  const resting = Array.from({ length: BAND_COUNT }, (_, i) => {
    const t = i / (BAND_COUNT - 1);
    return 0.06 + 0.1 * Math.sin(Math.PI * t);
  });
  const silent = new Array(BAND_COUNT).fill(0);

  let canvas = null;
  let g = null;
  let width = 0;
  let height = 0;
  let ink = [23, 23, 28];
  let smoothed = silent;
  let reduced = false;

  const fit = (layout) => {
    const dpr = window.devicePixelRatio || 1;
    width = layout.width;
    height = layout.height;
    canvas.width = Math.max(1, Math.round(width * dpr));
    canvas.height = Math.max(1, Math.round(height * dpr));
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
  };

  const readInk = (colors) => {
    ink = colors.ink.map((v) => Math.round(v * 255));
  };

  // One filled silhouette: a smooth curve through the bands closed down to the floor, joined by quadratic
  // midpoints so it reads as a continuous horizon, not stepped bars.
  const draw = (bands) => {
    g.clearRect(0, 0, width, height);
    const last = bands.length - 1;
    if (last < 1) return;
    const xAt = (i) => (i / last) * width;
    const yAt = (v) => height - Math.min(1, Math.max(0, v)) * height * MAX_AMP;
    g.beginPath();
    g.moveTo(0, height);
    g.lineTo(0, yAt(bands[0]));
    for (let i = 0; i < last; i++) {
      const mx = (xAt(i) + xAt(i + 1)) / 2;
      const my = (yAt(bands[i]) + yAt(bands[i + 1])) / 2;
      g.quadraticCurveTo(xAt(i), yAt(bands[i]), mx, my);
    }
    g.lineTo(xAt(last), yAt(bands[last]));
    g.lineTo(width, height);
    g.closePath();
    const grad = g.createLinearGradient(0, height, 0, 0);
    const rgb = `${ink[0]}, ${ink[1]}, ${ink[2]}`;
    grad.addColorStop(0, `rgba(${rgb}, ${BASE_ALPHA})`);
    grad.addColorStop(0.55, `rgba(${rgb}, ${MID_ALPHA})`);
    grad.addColorStop(1, `rgba(${rgb}, 0)`);
    g.fillStyle = grad;
    g.fill();
  };

  plistoVis.raw({
    setup(ctx) {
      canvas = document.createElement("canvas");
      canvas.style.cssText = "position:fixed;inset:0;width:100%;height:100%;display:block";
      document.body.appendChild(canvas);
      g = canvas.getContext("2d");
      reduced = ctx.reducedMotion;
      readInk(ctx.colors);
      fit(ctx.layout);
      return canvas;
    },
    frame(f) {
      if (f.still || reduced) {
        draw(resting);
        return;
      }
      smoothed = smoothBands(smoothed, f.rawBands.length > 0 ? f.rawBands : silent, ATTACK, DECAY);
      draw(smoothed);
    },
    resize: fit,
    theme(ctx) {
      readInk(ctx.colors);
    },
    dispose() {
      canvas.remove();
    },
  });
})();
